SourceCode.Declaration:
// Recommended: the batch framework's write runs first;
// telemetry runs outside its transaction.
// Preferred long-term option: delete this extension (and the BatchJob.update / job-end
// delegate hooks) and use the built-in batch signals of Monitoring and Telemetry.
[ExtensionOf(tableStr(Batch))]
public final class ISMBatch_Extension
{
}

Method.Source:
public void update()
{
    BatchStatus newStatus     = this.Status;
    boolean     statusChanged = newStatus != this.orig().Status;
    container   telemetryArgs;

    if (statusChanged)
    {
        // Capture before/after images now;
        // orig() reflects the new values after the update.
        telemetryArgs = [this.orig(), this,
                         ISMTelemetryEventNames::BatchStatusUpdate];
    }

    next update();

    if (statusChanged
        && (newStatus == BatchStatus::Finished
            || newStatus == BatchStatus::Error
            || newStatus == BatchStatus::Canceled))
    {
        // Same pattern ISMBatchJob_Extension.insert() already uses:
        // logBatchJobAsync runs in a separate session with ttsLevel 0,
        // where the catch in ISMTelemetryBase.processEvent works.
        runAsync(classNum(ISMTelemetryBatch),
                 staticMethodStr(ISMTelemetryBatch, logBatchJobAsync),
                 telemetryArgs);
    }
}
